def anagram_mapping(a, b):
    pos = {}
    for j, x in enumerate(b):
        pos.setdefault(x, []).append(j)
    used = {}
    out = []
    for x in a:
        i = used.get(x, 0)
        out.append(pos[x][i])
        used[x] = i + 1
    return out
